type AllowedMCPServer struct {
	// Name of the MCP server that users are allowed to configure                                 
	ServerName                                                                           *string  `json:"serverName,omitempty"`
	// Exact command and arguments used to start stdio servers                                    
	ServerCommand                                                                        []string `json:"serverCommand,omitempty"`
	// URL pattern for remote servers, supports wildcards (e.g., https://*.example.com/*)         
	ServerURL                                                                            *string  `json:"serverUrl,omitempty"`
}

// Customize attribution for git commits and pull requests. See
// https://code.claude.com/docs/en/settings#attribution-settings
type Attribution struct {
	// Attribution for git commits, including any trailers. Empty string hides commit attribution        
	Commit                                                                                       *string `json:"commit,omitempty"`
	// Attribution for pull request descriptions. Empty string hides pull request attribution            
	PR                                                                                           *string `json:"pr,omitempty"`
}

// Customization for the auto mode classifier prompt. Typically configured in managed
// settings to tune the allow/deny rules used when permissions.defaultMode is "auto". By
// default, allow, soft_deny, and environment REPLACE the corresponding built-in classifier
// section entirely. Include the literal string "$defaults" as an array entry (added in
// v2.1.118) to splice the built-in defaults in at that position alongside your custom
// rules. See https://code.claude.com/docs/en/permissions
type AutoMode struct {
	// Rules for the auto mode classifier allow section. Replaces the built-in allow rules               
	// entirely unless the literal string "$defaults" is included as an entry, which splices the         
	// built-in defaults in at that position.                                                            
	Allow                                                                                       []string `json:"allow,omitempty"`
	// Entries for the auto mode classifier environment section. Replaces the built-in                   
	// environment context entirely unless the literal string "$defaults" is included as an              
	// entry, which splices the built-in defaults in at that position.                                   
	Environment                                                                                 []string `json:"environment,omitempty"`
	// Rules for the auto mode classifier soft-deny section. Replaces the built-in soft-deny             
	// rules entirely unless the literal string "$defaults" is included as an entry, which               
	// splices the built-in defaults in at that position.                                                
	SoftDeny                                                                                    []string `json:"soft_deny,omitempty"`
}

