// Custom commands to run before/after tool executions. See
// https://code.claude.com/docs/en/hooks
type HooksClass struct {
	// Hooks that run when settings, managed settings, or skill files change during a session.                         
	// Supports matchers: user_settings, project_settings, local_settings, policy_settings,                            
	// skills. Command handlers only. Exit code 2 blocks the change (except policy_settings                            
	// which is audit-only). See https://code.claude.com/docs/en/hooks#configchange                                    
	ConfigChange                                                                                 []ConfigChangeElement `json:"ConfigChange,omitempty"`
	// Hooks that run when the working directory changes. Provides cwd (new directory) and                             
	// previous_cwd. Matchers are ignored; fires on every directory change. See                                        
	// https://code.claude.com/docs/en/hooks#cwdchanged                                                                
	CwdChanged                                                                                   []ConfigChangeElement `json:"CwdChanged,omitempty"`
	// Hooks that run when an MCP server requests user input during a tool call. See                                   
	// https://code.claude.com/docs/en/hooks                                                                           
	Elicitation                                                                                  []ConfigChangeElement `json:"Elicitation,omitempty"`
	// Hooks that run after a user responds to an MCP elicitation, before the response is sent                         
	// back to the server. See https://code.claude.com/docs/en/hooks                                                   
	ElicitationResult                                                                            []ConfigChangeElement `json:"ElicitationResult,omitempty"`
	// Hooks that run when a watched file is created, modified, or deleted. Supports filename                          
	// matchers. Provides file_path and file_event_type (created, modified, deleted). See                              
	// https://code.claude.com/docs/en/hooks#filechanged                                                               
	FileChanged                                                                                  []ConfigChangeElement `json:"FileChanged,omitempty"`
	// Hooks that run when a CLAUDE.md or .claude/rules/*.md file is loaded into context. Fires                        
	// at session start and when files are lazily loaded (e.g., nested traversal, path glob                            
	// match). No decision control; used for audit logging and observability. Does not support                         
	// matchers. See https://code.claude.com/docs/en/hooks#instructionsloaded                                          
	InstructionsLoaded                                                                           []ConfigChangeElement `json:"InstructionsLoaded,omitempty"`
	// Hooks that trigger on notifications                                                                             
	Notification                                                                                 []ConfigChangeElement `json:"Notification,omitempty"`
	// Hooks that run when a tool call is denied by the auto mode classifier. Supports matchers                        
	// on tool name. See https://code.claude.com/docs/en/hooks                                                         
	PermissionDenied                                                                             []ConfigChangeElement `json:"PermissionDenied,omitempty"`
	// Hooks that run when a permission dialog appears                                                                 
	PermissionRequest                                                                            []ConfigChangeElement `json:"PermissionRequest,omitempty"`
	// Hooks that run after the context is compacted. See https://code.claude.com/docs/en/hooks                        
	PostCompact                                                                                  []ConfigChangeElement `json:"PostCompact,omitempty"`
	// Hooks that run after a full batch of parallel tool calls resolves, before the next model                        
	// call. Exit code 2 blocks the agentic loop. Does not support matchers. See                                       
	// https://code.claude.com/docs/en/hooks                                                                           
	PostToolBatch                                                                                []ConfigChangeElement `json:"PostToolBatch,omitempty"`
	// Hooks that run after tool completion                                                                            
	PostToolUse                                                                                  []ConfigChangeElement `json:"PostToolUse,omitempty"`
	// Hooks that run after a tool fails                                                                               
	PostToolUseFailure                                                                           []ConfigChangeElement `json:"PostToolUseFailure,omitempty"`
	// Hooks that run before the context is compacted                                                                  
	PreCompact                                                                                   []ConfigChangeElement `json:"PreCompact,omitempty"`
	// Hooks that run before tool calls                                                                                
	PreToolUse                                                                                   []ConfigChangeElement `json:"PreToolUse,omitempty"`
	// Hooks that run when a session ends                                                                              
	SessionEnd                                                                                   []ConfigChangeElement `json:"SessionEnd,omitempty"`
	// Hooks that run when a new session starts                                                                        
	SessionStart                                                                                 []ConfigChangeElement `json:"SessionStart,omitempty"`
	// UNDOCUMENTED. Hooks that run during repository initialization (--init, --init-only) or                          
	// maintenance (--maintenance)                                                                                     
	Setup                                                                                        []ConfigChangeElement `json:"Setup,omitempty"`
	// Hooks that run when agents finish responding. Does not run on user interrupt                                    
	Stop                                                                                         []ConfigChangeElement `json:"Stop,omitempty"`
	// Hooks that run when a turn ends due to an API error (e.g., rate_limit,                                          
	// authentication_failed, billing_error, invalid_request, server_error, max_output_tokens,                         
	// unknown). Matcher can scope to specific error types. Hook output and exit code are                              
	// ignored. See https://code.claude.com/docs/en/hooks                                                              
	StopFailure                                                                                  []ConfigChangeElement `json:"StopFailure,omitempty"`
	// Hooks that run when a subagent is spawned                                                                       
	SubagentStart                                                                                []ConfigChangeElement `json:"SubagentStart,omitempty"`
	// Hooks that run when subagents finish responding                                                                 
	SubagentStop                                                                                 []ConfigChangeElement `json:"SubagentStop,omitempty"`
	// Hooks that run when a task is being marked as completed. Exit code 2 prevents completion                        
	// and sends feedback. Does not support matchers. See                                                              
	// https://code.claude.com/docs/en/hooks#taskcompleted                                                             
	TaskCompleted                                                                                []ConfigChangeElement `json:"TaskCompleted,omitempty"`
	// Hooks that run when a task is being created via TaskCreate. Exit code 2 rolls back task                         
	// creation. Does not support matchers. See https://code.claude.com/docs/en/hooks#taskcreated                      
	TaskCreated                                                                                  []ConfigChangeElement `json:"TaskCreated,omitempty"`
	// Hooks that run when an agent team teammate is about to go idle. Exit code 2 sends                               
	// feedback and keeps the teammate working. Does not support matchers. Agent teams are                             
	// experimental. See https://code.claude.com/docs/en/hooks#teammateidle                                            
	TeammateIdle                                                                                 []ConfigChangeElement `json:"TeammateIdle,omitempty"`
	// Hooks that run when a user-typed command expands into a prompt, before it reaches Claude.                       
	// Exit code 2 blocks the expansion. Supports matchers on command name. See                                        
	// https://code.claude.com/docs/en/hooks                                                                           
	UserPromptExpansion                                                                          []ConfigChangeElement `json:"UserPromptExpansion,omitempty"`
	// Hooks that run when a user submits a prompt                                                                     
	UserPromptSubmit                                                                             []ConfigChangeElement `json:"UserPromptSubmit,omitempty"`
	// Hooks that run when a worktree is created via --worktree or isolation: "worktree" in                            
	// subagents. Command handlers only, no matchers. Hook must print absolute path to created                         
	// worktree on stdout; non-zero exit fails creation. See                                                           
	// https://code.claude.com/docs/en/hooks#worktreecreate                                                            
	WorktreeCreate                                                                               []ConfigChangeElement `json:"WorktreeCreate,omitempty"`
	// Hooks that run when a worktree is being removed at session exit or when a subagent                              
	// finishes. Command handlers only, no matchers. Used for cleanup tasks; cannot block                              
	// removal. See https://code.claude.com/docs/en/hooks#worktreeremove                                               
	WorktreeRemove                                                                               []ConfigChangeElement `json:"WorktreeRemove,omitempty"`
}

// Hook matcher configuration with multiple hooks
type ConfigChangeElement struct {
	// Array of hooks to execute                                                                              
	Hooks                                                                                       []HookElement `json:"hooks"`
	// Optional pattern to match event contexts, case-sensitive. Behavior depends on event type.              
	// See https://code.claude.com/docs/en/hooks#matcher-patterns for event-specific details and              
	// examples                                                                                               
	Matcher                                                                                     *string       `json:"matcher,omitempty"`
}

// Bash command hook
//
// LLM prompt hook. See https://code.claude.com/docs/en/hooks#prompt-based-hooks
//
// Agent hook with multi-turn tool access for verification. See
// https://code.claude.com/docs/en/hooks#agent-based-hooks
//
// HTTP webhook hook. POST JSON to a URL and receive JSON response. See
// https://code.claude.com/docs/en/hooks#http-hook-fields
//
// MCP tool hook. Call a tool on an already-connected MCP server. See
// https://code.claude.com/docs/en/hooks#mcp-tool-hook-fields
type HookElement struct {
	// Run this hook asynchronously without blocking Claude Code                                                       
	Async                                                                                       *bool                  `json:"async,omitempty"`
	// When true, the hook runs in the background and wakes the model when it exits with code 2.                       
	// Implies async.                                                                                                  
	AsyncRewake                                                                                 *bool                  `json:"asyncRewake,omitempty"`
	// Shell command to execute                                                                                        
	Command                                                                                     *string                `json:"command,omitempty"`
	// Optional permission-rule-syntax filter (e.g., "Bash(git *)"). Evaluated only on                                 
	// tool-related events (PreToolUse, PostToolUse, PostToolUseFailure, PermissionRequest,                            
	// PermissionDenied); on other events a hook with `if` set never runs. See                                         
	// https://code.claude.com/docs/en/hooks-guide#filter-hooks-with-matchers                                          
	//                                                                                                                 
	// Optional permission-rule-syntax filter. Evaluated only on tool-related events                                   
	// (PreToolUse, PostToolUse, PostToolUseFailure, PermissionRequest, PermissionDenied); on                          
	// other events a hook with `if` set never runs. See                                                               
	// https://code.claude.com/docs/en/hooks-guide#filter-hooks-with-matchers                                          
	If                                                                                          *string                `json:"if,omitempty"`
	// Shell interpreter for the command. "bash" uses the login shell (bash/zsh/sh);                                   
	// "powershell" uses pwsh. Defaults to bash.                                                                       
	Shell                                                                                       *Shell                 `json:"shell,omitempty"`
	// Custom spinner message displayed while the hook runs                                                            
	StatusMessage                                                                               *string                `json:"statusMessage,omitempty"`
	// Optional timeout in seconds                                                                                     
	//                                                                                                                 
	// Optional timeout in seconds (default: 30)                                                                       
	//                                                                                                                 
	// Optional timeout in seconds (default: 60)                                                                       
	Timeout                                                                                     *float64               `json:"timeout,omitempty"`
	// Hook type                                                                                                       
	Type                                                                                        HookType               `json:"type"`
	// Model to use for evaluation. Defaults to a fast model                                                           
	Model                                                                                       *string                `json:"model,omitempty"`
	// Prompt to evaluate with LLM. Use $ARGUMENTS placeholder for hook input JSON.                                    
	//                                                                                                                 
	// Prompt describing what to verify. Use $ARGUMENTS placeholder for hook input JSON.                               
	Prompt                                                                                      *string                `json:"prompt,omitempty"`
	// List of environment variable names permitted for interpolation in headers. If not set, no                       
	// env var interpolation is allowed.                                                                               
	AllowedEnvVars                                                                              []string               `json:"allowedEnvVars,omitempty"`
	// Custom HTTP headers (e.g., Authorization: Bearer token). Values support $VAR_NAME or                            
	// ${VAR_NAME} interpolation.                                                                                      
	Headers                                                                                     map[string]string      `json:"headers,omitempty"`
	// URL to POST hook input JSON to. Endpoint must accept POST requests and return JSON.                             
	URL                                                                                         *string                `json:"url,omitempty"`
	// Arguments passed to the tool. String values support ${path} substitution from hook JSON                         
	// input (e.g., ${tool_input.file_path}, ${cwd})                                                                   
	Input                                                                                       map[string]interface{} `json:"input,omitempty"`
	// Name of a configured MCP server (must already be connected)                                                     
	Server                                                                                      *string                `json:"server,omitempty"`
	// Name of the tool to call on that server                                                                         
	Tool                                                                                        *string                `json:"tool,omitempty"`
}

// Tool usage permissions configuration.
// See https://code.claude.com/docs/en/permissions and
// https://code.claude.com/docs/en/settings#permission-settings
// See https://code.claude.com/docs/en/tools-reference for full list of tools available to
// Claude.
type Permissions struct {
	// Additional directories to include in the permission scope                                                                
	AdditionalDirectories                                                                      []string                         `json:"additionalDirectories,omitempty"`
	// List of permission rules for allowed operations                                                                          
	Allow                                                                                      []string                         `json:"allow,omitempty"`
	// List of permission rules that should always prompt for confirmation                                                      
	Ask                                                                                        []string                         `json:"ask,omitempty"`
	// Default permission mode.                                                                                                 
	// "default": prompts on first use.                                                                                         
	// "acceptEdits": auto-accepts file edits.                                                                                  
	// "plan": read-only, no modifications.                                                                                     
	// UNDOCUMENTED. "delegate": coordination-only for agent team leads (agent teams are                                        
	// experimental; enable via CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS).                                                          
	// "dontAsk": auto-denies unless pre-approved via permissions.                                                              
	// "bypassPermissions": skips all prompts (use only in isolated environments).                                              
	// "auto": auto-approves tool calls with background safety checks that verify actions align                                 
	// with your request.                                                                                                       
	// See https://code.claude.com/docs/en/permissions                                                                          
	DefaultMode                                                                                *DefaultMode                     `json:"defaultMode,omitempty"`
	// List of permission rules for denied operations                                                                           
	Deny                                                                                       []string                         `json:"deny,omitempty"`
	// Set to "disable" to prevent auto mode from being activated. Removes `auto` from the                                      
	// Shift+Tab cycle and rejects `--permission-mode auto` at startup. Most useful in managed                                  
	// settings where users cannot override it. See https://code.claude.com/docs/en/permissions                                 
	DisableAutoMode                                                                            *DisableDeepLinkRegistrationEnum `json:"disableAutoMode,omitempty"`
	// Disable the ability to bypass permission prompts                                                                         
	DisableBypassPermissionsMode                                                               *DisableDeepLinkRegistrationEnum `json:"disableBypassPermissionsMode,omitempty"`
}

type PluginConfig struct {
	// User configuration values for MCP servers keyed by server name                                                         
	MCPServers                                                                                 map[string]map[string]*Default `json:"mcpServers,omitempty"`
	// Non-sensitive option values from the plugin manifest's userConfig, keyed by option name.                               
	// Sensitive values go to secure storage instead. See                                                                     
	// https://code.claude.com/docs/en/plugins-reference                                                                      
	Options                                                                                    map[string]*Default            `json:"options,omitempty"`
}

// Sandbox execution configuration. See https://code.claude.com/docs/en/sandboxing
type Sandbox struct {
	// Allow commands to run outside the sandbox via the dangerouslyDisableSandbox parameter.                      
	// When false, the dangerouslyDisableSandbox parameter is completely ignored and all                           
	// commands must run sandboxed. Default: true. See                                                             
	// https://code.claude.com/docs/en/sandboxing#limitations                                                      
	AllowUnsandboxedCommands                                                                   *bool               `json:"allowUnsandboxedCommands,omitempty"`
	// Automatically allow bash commands without prompting when they run in the sandbox. Only                      
	// applies to commands that will run sandboxed. See                                                            
	// https://code.claude.com/docs/en/sandboxing#sandbox-modes                                                    
	AutoAllowBashIfSandboxed                                                                   *bool               `json:"autoAllowBashIfSandboxed,omitempty"`
	// Enable sandboxed bash. See https://code.claude.com/docs/en/sandboxing#enable-sandboxing                     
	Enabled                                                                                    *bool               `json:"enabled,omitempty"`
	// Enable weaker sandbox mode for unprivileged docker environments where --proc mounting                       
	// fails. This significantly reduces the strength of the sandbox and should only be used                       
	// when this risk is acceptable. Default: false (secure). See                                                  
	// https://code.claude.com/docs/en/sandboxing#limitations                                                      
	EnableWeakerNestedSandbox                                                                  *bool               `json:"enableWeakerNestedSandbox,omitempty"`
	// macOS only. Allow access to the system TLS trust service (com.apple.trustd.agent) in the                    
	// sandbox. Required for Go-based tools like gh, gcloud, and terraform to verify TLS                           
	// certificates when using httpProxyPort with a MITM proxy and custom CA. Reduces security                     
	// by opening a potential data exfiltration path. Default: false. See                                          
	// https://code.claude.com/docs/en/settings#sandbox-settings                                                   
	EnableWeakerNetworkIsolation                                                               *bool               `json:"enableWeakerNetworkIsolation,omitempty"`
	// Commands that should never run in the sandbox (e.g., ["git", "docker"]). See                                
	// https://code.claude.com/docs/en/sandboxing#configure-sandboxing                                             
	ExcludedCommands                                                                           []string            `json:"excludedCommands,omitempty"`
	// Filesystem access control for sandboxed commands. See                                                       
	// https://code.claude.com/docs/en/sandboxing#filesystem-isolation                                             
	Filesystem                                                                                 *Filesystem         `json:"filesystem,omitempty"`
	// Map of command patterns to filesystem paths to ignore violations for. Use "*" to match                      
	// all commands                                                                                                
	IgnoreViolations                                                                           map[string][]string `json:"ignoreViolations,omitempty"`
	// Configures network isolation settings for the sandboxed bash environment, including                         
	// domain restrictions, Unix socket access, and custom proxy configuration.                                    
	Network                                                                                    *Network            `json:"network,omitempty"`
	// Custom ripgrep configuration for Claude Code's bundled ripgrep support. Overrides the                       
	// bundled binary and arguments.                                                                               
	Ripgrep                                                                                    *Ripgrep            `json:"ripgrep,omitempty"`
}

// Filesystem access control for sandboxed commands. See
// https://code.claude.com/docs/en/sandboxing#filesystem-isolation
type Filesystem struct {
	// (Managed settings only) When true, only allowRead paths from managed settings are used;               
	// user, project, and local allowRead entries are ignored. denyRead still merges from all                
	// sources. See https://code.claude.com/docs/en/sandboxing#filesystem-isolation                          
	AllowManagedReadPathsOnly                                                                       *bool    `json:"allowManagedReadPathsOnly,omitempty"`
	// Paths to re-allow reading within denyRead regions. Takes precedence over denyRead for                 
	// matching paths. See                                                                                   
	// https://code.claude.com/docs/en/sandboxing#granting-subprocess-write-access-to-specific-paths         
	AllowRead                                                                                       []string `json:"allowRead,omitempty"`
	// Paths where subprocesses are allowed to write. Supports prefixes: // (absolute), ~/ (home             
	// directory), / (relative to settings file), ./ or no prefix (relative path). See                       
	// https://code.claude.com/docs/en/sandboxing#granting-subprocess-write-access-to-specific-paths         
	AllowWrite                                                                                      []string `json:"allowWrite,omitempty"`
	// Paths where subprocesses are explicitly denied read access. See                                       
	// https://code.claude.com/docs/en/sandboxing#filesystem-isolation                                       
	DenyRead                                                                                        []string `json:"denyRead,omitempty"`
	// Paths where subprocesses are explicitly denied write access. Takes precedence over                    
	// allowWrite. See https://code.claude.com/docs/en/sandboxing#filesystem-isolation                       
	DenyWrite                                                                                       []string `json:"denyWrite,omitempty"`
}

// Configures network isolation settings for the sandboxed bash environment, including
// domain restrictions, Unix socket access, and custom proxy configuration.
type Network struct {
	// Allow all Unix domain socket connections. If true, this overrides allowUnixSockets. See           
	// https://code.claude.com/docs/en/sandboxing#network-isolation                                      
	AllowAllUnixSockets                                                                         *bool    `json:"allowAllUnixSockets,omitempty"`
	// Allowlist of network domains for sandboxed commands. Supports wildcard patterns like              
	// *.example.com. See https://code.claude.com/docs/en/sandboxing#network-isolation                   
	AllowedDomains                                                                              []string `json:"allowedDomains,omitempty"`
	// Allow binding to local network addresses (e.g., localhost ports). Defaults to false if            
	// not specified. See https://code.claude.com/docs/en/sandboxing#network-isolation                   
	AllowLocalBinding                                                                           *bool    `json:"allowLocalBinding,omitempty"`
	// macOS only. Additional XPC/Mach service names the sandbox may look up. Supports a single          
	// trailing * for prefix matching. Needed for tools that communicate via XPC such as the iOS         
	// Simulator or Playwright. See https://code.claude.com/docs/en/sandboxing#network-isolation         
	AllowMachLookup                                                                             []string `json:"allowMachLookup,omitempty"`
	// (Managed settings only) Only allowedDomains and WebFetch(domain:...) allow rules from             
	// managed settings are respected. User, project, local, and flag settings domains are               
	// ignored. Denied domains are still respected from all sources. Non-allowed domains are             
	// automatically blocked without user prompts. See                                                   
	// https://code.claude.com/docs/en/sandboxing#network-isolation                                      
	AllowManagedDomainsOnly                                                                     *bool    `json:"allowManagedDomainsOnly,omitempty"`
	// Allow Unix domain sockets for local IPC (SSH agent, Docker, etc.). Provide an array of            
	// specific paths. Defaults to blocking if not specified. See                                        
	// https://code.claude.com/docs/en/sandboxing#network-isolation                                      
	AllowUnixSockets                                                                            []string `json:"allowUnixSockets,omitempty"`
	// Blocklist of network domains for sandboxed commands. Blocks specific domains even when a          
	// broader allowedDomains wildcard would otherwise permit them. Supports wildcard patterns           
	// like *.example.com. See https://code.claude.com/docs/en/sandboxing#network-isolation              
	DeniedDomains                                                                               []string `json:"deniedDomains,omitempty"`
	// HTTP proxy port to use for network filtering. If not specified, a proxy server will be            
	// started automatically. See                                                                        
	// https://code.claude.com/docs/en/sandboxing#custom-proxy-configuration                             
	HTTPProxyPort                                                                               *int64   `json:"httpProxyPort,omitempty"`
	// SOCKS proxy port to use for network filtering. If not specified, a proxy server will be           
	// started automatically. See                                                                        
	// https://code.claude.com/docs/en/sandboxing#custom-proxy-configuration                             
	SocksProxyPort                                                                              *int64   `json:"socksProxyPort,omitempty"`
}

// Custom ripgrep configuration for Claude Code's bundled ripgrep support. Overrides the
